Adds a list validation restricted to two choices and a decimal range validation with a Between operator to two cell areas, saves the workbook to bytes, reloads it and reads each validation's type, operator and formulas back from the reloaded sheet.

Example:
// Authored example: add a list data validation and a decimal range validation, then read them back.
use aspose_cells_foss_rust::{CellArea, OperatorType, ValidationType, Workbook};
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    let mut workbook = Workbook::new();
    {
        let mut worksheets = workbook.get_worksheets_mut();
        let sheet = worksheets.get(0)?;
        let mut cells = sheet.get_cells_mut();
        cells.get("A1")?.put_value_string("Open")?;
        cells.get("B2")?.put_value_i32(5)?;

        let mut validations = sheet.get_validations();
        let list_index = validations.add(CellArea::create_cell_area_a1("A1", "A3")?)?;
        let mut list_validation = validations.get(list_index).expect("validation should exist");
        list_validation.set_type(ValidationType::List);
        list_validation.set_formula1("\"Open,Closed\"");

        let decimal_index = validations.add(CellArea::create_cell_area_a1("B2", "B3")?)?;
        let mut decimal_validation = validations
            .get(decimal_index)
            .expect("validation should exist");
        decimal_validation.set_type(ValidationType::Decimal);
        decimal_validation.set_operator(OperatorType::Between);
        decimal_validation.set_formula1("1.5");
        decimal_validation.set_formula2("9.5");
    }

    let bytes = workbook.save_xlsx_to_bytes()?;
    let mut loaded = Workbook::load_xlsx_from_bytes(&bytes)?;
    let mut sheets = loaded.get_worksheets_mut();
    let sheet = sheets.get(0)?;
    let mut validations = sheet.get_validations();
    let validation_count = validations.count();

    let (a1_type, a1_formula1) = {
        let a1 = validations
            .get_validation_in_cell(0, 0)?
            .expect("A1 validation should exist");
        (a1.get_type(), a1.get_formula1().to_string())
    };
    let (b2_type, b2_operator, b2_formula1, b2_formula2) = {
        let b2 = validations
            .get_validation_in_cell(1, 1)?
            .expect("B2 validation should exist");
        (
            b2.get_type(),
            b2.get_operator(),
            b2.get_formula1().to_string(),
            b2.get_formula2().to_string(),
        )
    };

    println!("validation count: {}", validation_count);
    println!("A1 type: {:?} formula1: {}", a1_type, a1_formula1);
    println!(
        "B2 type: {:?} formula1: {} formula2: {}",
        b2_type, b2_formula1, b2_formula2
    );

    assert_eq!(validation_count, 2);
    assert_eq!(a1_type, ValidationType::List);
    assert_eq!(a1_formula1, "\"Open,Closed\"");
    assert_eq!(b2_type, ValidationType::Decimal);
    assert_eq!(b2_operator, OperatorType::Between);
    Ok(())
}
